/** Flat array of all places across all regions */
export const ALL_PLACES: Place[] = PLACE_REGIONS.flatMap((r) => r.places);

/** Look up a place by id */
export function getPlaceById(id: string): Place | undefined {
  return ALL_PLACES.find((p) => p.id === id);
}

/** Format the local time at a place using its IANA timezone */
export function formatLocalTime(date: Date, timezone: string): string {
  return date.toLocaleTimeString('en-GB', {
    timeZone: timezone,
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });
}

/** Format the local day + date at a place using its IANA timezone */
export function formatLocalDay(date: Date, timezone: string): string {
  return date.toLocaleDateString('en-GB', {
    timeZone: timezone,
    weekday: 'short',
    day: 'numeric',
    month: 'short',
  });
}

/** Format UTC time */
export function formatUTC(date: Date): string {
  return date.toLocaleTimeString('en-GB', {
    timeZone: 'UTC',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  });
}

