/**
 * Build 3-level NavEntry tree: Region > Country > City.
 * Optionally prepend a "Recent" section from a list of place IDs.
 */
export function buildNavEntries(recentIds: string[] = []): NavEntry[] {
  const entries: NavEntry[] = [];

  // ── Recent ──────────────────────────────────────────────────────────────────
  if (recentIds.length > 0) {
    const recentPlaces = recentIds
      .map((id) => ALL_PLACES.find((p) => p.id === id))
      .filter((p): p is Place => p !== undefined);

    entries.push({
      id: '__recent__',
      name: 'Recent',
      icon: '🕐',
      defaultOpen: true,
      children: recentPlaces.map((p) => ({
        id: p.id,
        name: p.name,
        icon: p.flag,
      })),
    });
  }

  // ── Region > Country > City ──────────────────────────────────────────────────
  for (const region of PLACE_REGIONS) {
    // Group places by country code
    const byCountry = new Map<string, Place[]>();
    for (const place of region.places) {
      const list = byCountry.get(place.country) ?? [];
      list.push(place);
      byCountry.set(place.country, list);
    }

    const countryEntries: NavEntry[] = [];
    for (const [code, places] of byCountry) {
      const info = COUNTRY_INFO[code];
      const countryName = info?.name ?? code;
      const countryFlag = info?.flag ?? '';

      countryEntries.push({
        id: `country-${code}`,
        name: countryName,
        icon: countryFlag,
        defaultOpen: false,
        children: places.map((p) => ({
          id: p.id,
          name: p.name,
          icon: p.flag,
        })),
      });
    }

    entries.push({
      id: region.id,
      name: region.name,
      icon: region.icon,
      defaultOpen: false,
      children: countryEntries,
    });
  }

  return entries;
}
